//! 🧪️ The actual shared turn executes original paid queue owners without changing any grant.
use crate::{RetirementQueue,observe_retirement_allocations,queue_bank::{bank,grant,poll,quoted,sync}};
use semio_framework_value_retirement::{RetirementDemand,retirement::{arc_custody::arc_bytes,turn::*},retained_clone::{RetainedCloneGrant,RetainedCloneStep}};
use semio_framework_value_factory::{ArtifactOwnedValueRetirementFactory,ErasedSnapshotRetirement,OwnedValueRetirementFactory,owned::FactoryOwnedRetirement};
use semio_framework_test_fixtures::fixture_text;
use std::sync::Arc;
#[test]
fn retirement_turn_original_queue_preserves_full_grants_all_physical_currencies_and_paused_custody(){
 let law:serde_json::Value=serde_json::from_str(fixture_text!("../../../🎟️turn/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for empty in [false,true]{for body in law["copyBudgets"].as_array().unwrap(){for cut in law["cancellationCuts"].as_array().unwrap(){
  let mut bank=bank();let capacity=law[if empty{"emptyCapacity"}else{"originalCapacity"}].as_u64().unwrap()as usize;let mut text=String::with_capacity(capacity);if !empty{text.push_str(&law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize));}let mut original=Some(text);let mut factory:Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>=Some(Arc::new(OwnedValueRetirementFactory::<String>::default()));let held=capacity+arc_bytes::<OwnedValueRetirementFactory<String>>();let mut queue=RetirementQueue::default();let mut births=0;let mut releases=0;
  while !queue.has_reserved_slot(){let reserve=grant(queue.reserve_demand().unwrap());let((turn,_),heap)=observe_retirement_allocations(||sync(&mut bank,reserve,1,|effect|queue.reserve_step(effect)));let p=turn.result.unwrap();assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);assert_eq!(p.copied_items,1);bank.post(p,reserve,heap);births+=heap.0;releases+=heap.1;}
  let admission=grant(FactoryOwnedRetirement::<String>::original_admission_demands(&original));let mut output=None;let((turn,_),heap)=observe_retirement_allocations(||poll(&mut bank,admission,1,|effect|FactoryOwnedRetirement::admit_original(&mut original,&mut factory,&mut output,effect)));let p=turn.result.unwrap().progress();assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);bank.post(p,admission,heap);births+=heap.0;releases+=heap.1;assert!(original.is_none()&&factory.is_none());
  let placement=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:RetirementQueue::placement_bytes::<dyn ErasedSnapshotRetirement>(),maximum_depth:queue.placement_depth(),..Default::default()};let((turn,_),heap)=observe_retirement_allocations(||sync(&mut bank,placement,1,|effect|queue.admit_retirement(&mut output,effect)));let p=turn.result.unwrap().unwrap();assert_eq!(p.retained_capacity_bytes,0);assert_eq!(heap,(0,0));assert!(output.is_none());bank.post(p,placement,heap);
  for turn in 0..1000000{
   let body=body.as_u64().unwrap()as usize;let(full,heap)=observe_retirement_allocations(||quoted(body,|b|queue.next_demand(b).unwrap()));assert_eq!(heap,(0,0));let demand=queue.next_demand(full.maximum_copy_bytes).unwrap();
   for under in [Some(RetainedCloneGrant{maximum_items:0,..full}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..full}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..full}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..full}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..full})].into_iter().flatten(){let mut calls=0;let(step,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,under,|_|->crate::RetainedWorkOutcome<(RetainedCloneStep,bool),crate::OriginalRetirementFailure>{calls+=1;unreachable!("undergrant touched original owner")}).result.unwrap());assert_eq!(calls,0);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
   let units=queue.next_computational_work(full.maximum_copy_bytes).unwrap();let(step,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,full,|actual|{assert_eq!(actual,full);let(turn,_)=poll(&mut bank,actual,units,|effect|queue.step(effect));crate::RetainedWorkOutcome{work:turn.work,result:turn.result.map(|step|(step,queue.terminal_is_empty()))}}).result.unwrap());let p=step.progress();assert!(p.fits(full));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);bank.post(p,full,heap);births+=heap.0;releases+=heap.1;if queue.terminal_is_empty(){break;}assert!(turn<999999,"original queue stalled");if turn==cut.as_u64().unwrap()as usize{let(same,heap)=observe_retirement_allocations(||queue);queue=same;assert_eq!(heap,(0,0));}
  }
  assert!(queue.terminal_is_empty());assert_eq!(releases,held+births);let(_,heap)=observe_retirement_allocations(||drop((queue,original)));assert_eq!(heap,(0,0));
 }}}
}
